//! Typed row materialization for query / raw-SQL results.
//!
//! [`IRow`] is the single materialization trait for result rows: it turns one
//! row of positional column values into `Self` without requiring the target to
//! be an entity. Three kinds of types implement it:
//!
//! - every entity, through the `impl IRow` generated by `#[derive(EntityType)]`;
//!   the historical [`crate::entity::IFromRow`] path is a compatibility alias
//!   of [`IRow`];
//! - `#[derive(FromRow)]` structs, for report/raw-SQL rows;
//! - tuples `(T1, ...)` of 1..=12 elements.
//!
//! [`IRow::from_row`] is the canonical entry point; [`IRow::from_values`] is a
//! compatibility alias that delegates to it. Mapping is positional: the
//! `SELECT` list order must match the struct field / tuple element order.
//! Providers return values without column names, so named matching is only
//! available for entities via [`IRow::from_row_named`].
//!
//! ```
//! use rust_ef::prelude::*;
//! use rust_ef::provider::DbValue;
//!
//! #[derive(FromRow)]
//! struct CategoryTotal {
//!     category: String,
//!     total: i64,
//! }
//!
//! # fn main() -> Result<(), EFError> {
//! let rows = vec![vec![
//!     DbValue::String("books".into()),
//!     DbValue::I64(150),
//! ]];
//! let totals: Vec<CategoryTotal> = materialize_rows(&rows)?;
//! assert_eq!(totals.len(), 1);
//!
//! let direct = CategoryTotal::from_row(&[
//!     DbValue::String("toys".into()),
//!     DbValue::I64(7),
//! ])?;
//! assert_eq!(direct.total, 7);
//! # Ok(())
//! # }
//! ```

use crate::error::{EFError, EFResult};
use crate::provider::{DbValue, DbValueConvertError};

/// A result-row type that can be materialized from positional column values.
///
/// This is the single row-materialization trait: entities, `#[derive(FromRow)]`
/// structs and tuples of 1..=12 elements all implement it. It does not require
/// the target to be an entity; entity-only materialization (named columns,
/// metadata) is exposed through [`from_row_named`](Self::from_row_named), whose
/// default implementation is bounded on [`IEntityType`](crate::entity::IEntityType).
pub trait IRow: Sized {
    /// Materializes `Self` from one row of positional column values.
    ///
    /// This is the canonical entry point. Implementations must return a typed
    /// [`EFError::TypeConversion`] when the row is too short or a value cannot
    /// be converted.
    fn from_row(values: &[DbValue]) -> EFResult<Self>;

    /// Materializes an entity from **named** column values, matching by
    /// database column name instead of position.
    ///
    /// This is the reorder-safe path: rows whose column order is not guaranteed
    /// to match the model declaration order (migrations that reordered columns,
    /// views, ad-hoc `SELECT` lists) must use this instead of
    /// [`from_row`](Self::from_row), which assigns by index.
    ///
    /// Only entity rows can be materialized by name, hence the
    /// [`IEntityType`](crate::entity::IEntityType) bound. The default
    /// implementation maps the entity's property columns (in model order) onto
    /// `columns` and delegates to `from_row`; it therefore assumes the same
    /// invariant positional materialization already relies on — the model
    /// property order is the `from_row` position order. The
    /// `#[derive(EntityType)]` macro overrides it with a direct, compile-time
    /// name match.
    fn from_row_named(columns: &[(&str, DbValue)]) -> EFResult<Self>
    where
        Self: crate::entity::IEntityType,
    {
        let meta = Self::entity_meta();
        let mut values = Vec::with_capacity(meta.properties.len());
        for property in &meta.properties {
            let column = property.column_name.as_ref();
            let value = columns
                .iter()
                .find(|(name, _)| *name == column)
                .map(|(_, value)| value.clone())
                .ok_or_else(|| {
                    EFError::type_conversion(format!(
                        "column `{column}` is missing from the named row for entity `{}`",
                        meta.type_name
                    ))
                })?;
            values.push(value);
        }
        Self::from_row(&values)
    }

    /// Compatibility alias for [`from_row`](Self::from_row).
    ///
    /// [`from_row`](Self::from_row) is the canonical entry point; this method
    /// exists so code written against the previous `IRow` API keeps compiling.
    fn from_values(values: &[DbValue]) -> EFResult<Self> {
        Self::from_row(values)
    }
}

/// Materializes every row with [`IRow::from_row`], preserving row order.
pub fn materialize_rows<R: IRow>(rows: &[Vec<DbValue>]) -> EFResult<Vec<R>> {
    rows.iter().map(|row| R::from_row(row)).collect()
}

/// Implements [`IRow`] for tuples of 1..=12 elements.
///
/// Each element is converted with `TryFrom<DbValue>`; a row whose length does
/// not match the tuple arity is rejected with a typed `EFError::TypeConversion`
/// naming the tuple type and the expected/actual column counts.
macro_rules! impl_tuple_row {
    ($($index:tt => $name:ident),+) => {
        impl<$($name),+> IRow for ($($name,)+)
        where
            $($name: TryFrom<DbValue, Error = DbValueConvertError>),+
        {
            fn from_row(values: &[DbValue]) -> EFResult<Self> {
                let expected = [$($index),+].len();
                let tuple_name = stringify!($($name),+);
                if values.len() != expected {
                    return Err(EFError::type_conversion(format!(
                        "row has {} value(s) but tuple `({})` needs exactly {}",
                        values.len(),
                        tuple_name,
                        expected
                    )));
                }
                Ok(($(
                    $name::try_from(values[$index].clone()).map_err(|error| {
                        EFError::type_conversion(format!(
                            "tuple `({})` column {} cannot be converted: {}",
                            tuple_name, $index, error
                        ))
                    })?,
                )+))
            }
        }
    };
}

impl_tuple_row!(0 => T1);
impl_tuple_row!(0 => T1, 1 => T2);
impl_tuple_row!(0 => T1, 1 => T2, 2 => T3);
impl_tuple_row!(0 => T1, 1 => T2, 2 => T3, 3 => T4);
impl_tuple_row!(0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5);
impl_tuple_row!(0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6);
impl_tuple_row!(0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7);
impl_tuple_row!(
    0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7, 7 => T8
);
impl_tuple_row!(
    0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7, 7 => T8, 8 => T9
);
impl_tuple_row!(
    0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7, 7 => T8, 8 => T9, 9 => T10
);
impl_tuple_row!(
    0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7, 7 => T8, 8 => T9, 9 => T10,
    10 => T11
);
impl_tuple_row!(
    0 => T1, 1 => T2, 2 => T3, 3 => T4, 4 => T5, 5 => T6, 6 => T7, 7 => T8, 8 => T9, 9 => T10,
    10 => T11, 11 => T12
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tuple_maps_values_by_position() {
        let row = [DbValue::I32(7), DbValue::String("north".into())];
        let mapped = <(i32, String) as IRow>::from_row(&row).expect("tuple row");
        assert_eq!(mapped, (7, "north".to_string()));
    }

    #[test]
    fn single_element_tuple_is_supported() {
        let mapped = <(i64,) as IRow>::from_row(&[DbValue::I64(42)]).expect("one-tuple row");
        assert_eq!(mapped.0, 42);
    }

    #[test]
    fn from_values_is_a_compatibility_alias_for_from_row() {
        let mapped = <(i32, String) as IRow>::from_values(&[
            DbValue::I32(7),
            DbValue::String("north".into()),
        ])
        .expect("compatibility alias");
        assert_eq!(mapped, (7, "north".to_string()));
    }

    #[test]
    fn short_row_is_a_type_conversion_error() {
        let err =
            <(i32, i32) as IRow>::from_row(&[DbValue::I32(1)]).expect_err("short row must fail");
        match err {
            EFError::TypeConversion(message, _) => {
                assert!(message.contains("needs exactly 2"), "unexpected: {message}");
            }
            other => panic!("expected TypeConversion, got {other:?}"),
        }
    }

    #[test]
    fn long_row_is_a_type_conversion_error() {
        let err = <(i32,) as IRow>::from_row(&[DbValue::I32(1), DbValue::I32(2)])
            .expect_err("long row must fail");
        assert!(matches!(err, EFError::TypeConversion(..)));
    }

    #[test]
    fn unconvertible_cell_is_a_type_conversion_error_naming_the_index() {
        let err = <(i32, i32) as IRow>::from_row(&[DbValue::I32(1), DbValue::String("x".into())])
            .expect_err("bad cell must fail");
        match err {
            EFError::TypeConversion(message, _) => {
                assert!(message.contains("column 1"), "unexpected: {message}");
            }
            other => panic!("expected TypeConversion, got {other:?}"),
        }
    }
}
